void addShardReplyForClusterShards(client *c, list *nodes) {
    serverAssert(listLength(nodes) > 0);
    addReplyMapLen(c, 2);
    addReplyBulkCString(c, "slots");

    /* A shard owns all the slots served by its nodes. Normally only the
     * primary owns slots, but after a failover the old (failed) primary can
     * still be part of the shard while its promoted replica owns the slots.
     * Therefore collect the slot info from every node in the shard instead
     * of relying only on the primary of the first node in the list. */
    int slot_info_pairs_count = 0;
    listIter li;
    listRewind(nodes, &li);
    for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
        clusterNode *node = listNodeValue(ln);
        if (node->slot_info_pairs != NULL) {
            serverAssert((node->slot_info_pairs_count % 2) == 0);
            slot_info_pairs_count += node->slot_info_pairs_count;
        }
    }

    addReplyArrayLen(c, slot_info_pairs_count);
    listRewind(nodes, &li);
    for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
        clusterNode *node = listNodeValue(ln);
        if (node->slot_info_pairs == NULL) continue;
        for (int i = 0; i < node->slot_info_pairs_count; i++) {
            addReplyLongLong(c, (unsigned long)node->slot_info_pairs[i]);
        }
    }

    addReplyBulkCString(c, "nodes");

